argv:
$ErrorActionPreference='Stop'
$t=Invoke-RestMethod -UseBasicParsing 'http://127.0.0.1:17410/json/list' -TimeoutSec 3
$target=@($t)|Where-Object { try { ([uri]$_.url).Host -eq 'bugbountyfoto6.files.com' } catch { $false } } | Select-Object -First 1
$ws=[Net.WebSockets.ClientWebSocket]::new();$cts=[Threading.CancellationTokenSource]::new();$cts.CancelAfter(6000)
$ws.ConnectAsync([uri]$target.webSocketDebuggerUrl,$cts.Token).GetAwaiter().GetResult()|Out-Null
$expr=@'
(async()=>{
 const a=[...document.querySelectorAll('a')].find(e=>(e.textContent||'').trim()==='authz-probe-20260930');
 if(!a) return JSON.stringify({error:'probe link not found'});
 const row=a.closest('tr');
 if(!row) return JSON.stringify({error:'probe row not found'});
 const b=[...row.querySelectorAll('button')].find(e=>(e.getAttribute('aria-label')||e.innerText||'').trim()==='More');
 if(!b) return JSON.stringify({error:'row More not found'});
 b.click(); await new Promise(r=>setTimeout(r,300));
 const els=[...document.querySelectorAll('[role="menuitem"],[role="option"],[role="menu"] button,[role="menu"] a')];
 return JSON.stringify(els.map((e,i)=>({i,text:(e.innerText||e.getAttribute('aria-label')||'').trim().replace(/\s+/g,' ').slice(0,140),role:e.getAttribute('role'),disabled:!!e.disabled})).filter(x=>x.text));
})()
'@
$payload=@{id=1;method='Runtime.evaluate';params=@{expression=$expr;returnByValue=$true;awaitPromise=$true}}|ConvertTo-Json -Depth 10 -Compress
$bytes=[Text.Encoding]::UTF8.GetBytes($payload)
$ws.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,$cts.Token).GetAwaiter().GetResult()|Out-Null
$buf=New-Object byte[] 131072
while($true){$ms=[IO.MemoryStream]::new();do{$r=$ws.ReceiveAsync([ArraySegment[byte]]::new($buf),$cts.Token).GetAwaiter().GetResult();if($r.Count){$ms.Write($buf,0,$r.Count)}}while(-not $r.EndOfMessage);$o=([Text.Encoding]::UTF8.GetString($ms.ToArray())|ConvertFrom-Json);if($o.id -eq 1){Write-Output $o.result.result.value;break}}
$ws.Dispose()
